// Testing OrderService with both approaches
@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository mockRepo;  // Fully fake repository

    @Spy
    private EmailService spyEmail = new EmailService();  // Real email service

    @InjectMocks
    private OrderService service;

    @Test
    void testPlaceOrder_withMock() {
        var order = new Order(1L, "Laptop");
        when(mockRepo.save(any())).thenReturn(order);  // Stub the mock

        var result = service.placeOrder(order);

        assertEquals(1L, result.id());  // Mock returned our stub
    }

    @Test
    void testPlaceOrder_withSpy() {
        var order = new Order(2L, "Mouse");
        doReturn(true).when(spyEmail).sendConfirmation(any());  // Intercept email only

        service.placeOrder(order);  // Real validateOrder() logic runs

        verify(spyEmail).sendConfirmation(order);  // Verify the intercepted call
    }
}

