@ExtendWith(MockitoExtension.class)  // Required to activate @InjectMocks
class OrderServiceTest {
    @Mock
    private OrderRepository mockRepository;

    @Mock
    private EmailService mockEmailService;

    @Mock
    private PaymentGateway mockPaymentGateway;

    @InjectMocks
    private OrderService service;  // Mockito creates: new OrderService(mockRepository, mockEmailService, mockPaymentGateway)

    @Test
    void testPlaceOrder() {
        var order = new Order(1L, "Laptop", 999.99);
        when(mockRepository.save(any())).thenReturn(order);
        when(mockPaymentGateway.charge(999.99)).thenReturn(true);

        var result = service.placeOrder(order);  // All mocks injected automatically

        assertEquals(1L, result.id());
        verify(mockEmailService).sendConfirmation(order);  // Verify interaction
    }
}

@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {
    @Spy
    private PaymentValidator spyValidator = new PaymentValidator();

    @Test
    void demonstrateProblem_whenThenReturn() {
        // PROBLEM: This calls the REAL validateCard() during setup
        // If validateCard() throws exception for invalid data, test setup fails
        when(spyValidator.validateCard("invalid")).thenReturn(true);
    }

    @Test
    void safeSolution_doReturnWhen() {
        // SAFE: This never calls the real validateCard() method
        doReturn(true).when(spyValidator).validateCard("invalid");

        var result = spyValidator.validateCard("invalid");
        assertEquals(true, result);  // Returns stubbed value
    }

    @Test
    void stubbingVoidMethod() {
        // when().then() doesn't work with void methods
        // Must use doNothing() or doThrow()
        doNothing().when(spyValidator).logTransaction(any());

        spyValidator.logTransaction("test");  // Does nothing
    }
}

// FAKE: Real implementation with simplified storage
class FakeOrderRepository implements OrderRepository {
    private final Map<Long, Order> orders = new HashMap<>();
    private long nextId = 1L;

    @Override
    public Order save(Order order) {
        if (order.id() == null) {
            order = new Order(nextId++, order.item(), order.price());
        }
        orders.put(order.id(), order);  // Real storage logic
        return order;
    }

    @Override
    public Optional<Order> findById(Long id) {
        return Optional.ofNullable(orders.get(id));  // Real lookup logic
    }
}

