@WebMvcTest(OrderController.class)  // Load only web layer
class OrderControllerTest {
    @Autowired
    private MockMvc mockMvc;

    @MockBean  // Replace service bean with mock
    private OrderService mockService;

    @Test
    void testGetOrder() throws Exception {
        var order = new Order(1L, "Laptop", 999.99);
        when(mockService.getOrder(1L)).thenReturn(Optional.of(order));  // Stub the mock

        mockMvc.perform(get("/orders/1"))
               .andExpect(status().isOk())
               .andExpect(jsonPath("$.item").value("Laptop"));
    }
}

@SpringBootTest  // Full application context
class OrderServiceIntegrationTest {
    @Autowired
    private OrderService service;

    @SpyBean  // Wrap real repository bean
    private OrderRepository spyRepo;

    @Test
    void testPlaceOrder_withSpyBean() {
        var order = new Order(null, "Mouse", 29.99);
        doReturn(new Order(1L, "Mouse", 29.99)).when(spyRepo).save(any());  // Stub save only

        var result = service.placeOrder(order);  // Real service logic runs

        assertEquals(1L, result.id());
        verify(spyRepo).save(any());  // Verify interaction with spy
    }
}

// FINAL CLASS: works automatically with Mockito 2.x+
final class PaymentGateway {
    public boolean charge(double amount) {
        // Real implementation hits external API
        return true;
    }
}

@Mock
private PaymentGateway mockGateway;  // Works despite final class

@Test
void testFinalClassMock() {
    when(mockGateway.charge(999.99)).thenReturn(true);
    assertTrue(mockGateway.charge(999.99));  // Mock works
}

// STATIC METHOD: requires mockStatic() in try-with-resources
class TimeUtils {
    public static LocalDateTime now() {
        return LocalDateTime.now();  // Real system time
    }
}

@Test
void testStaticMethodMock() {
    try (var mockedStatic = mockStatic(TimeUtils.class)) {
        var fixedTime = LocalDateTime.of(2024, 1, 1, 12, 0);
        mockedStatic.when(TimeUtils::now).thenReturn(fixedTime);  // Stub static

        assertEquals(fixedTime, TimeUtils.now());  // Returns stubbed value
    }  // Mock auto-closes, static method restored

    assertNotEquals(fixedTime, TimeUtils.now());  // Real method again
}
